import json,re
from pathlib import Path
items=[]
def add(group, text):
 for line in text.strip().splitlines():
  en,ko,idea,example,before,after,caution=line.split('|')
  slug=re.sub(r'[^a-z0-9]+','-',en.lower()).strip('-')
  items.append(dict(id=slug,group=group,en=en,ko=ko,idea=idea,example=example,before=before.split(' / '),after=after.split(' / '),caution=caution))
